/* @motion
[Bell ring] bell icon
--ring-dur: Duration
--ring-angle: Angle
--ring-ease: Easing
[Badge open] badge dot
--badge-slide-dur: Slide duration
--badge-pop-dur: Pop duration
--badge-pop-ease: Pop easing
more --badge-fade-dur: Fade duration
more --badge-slide-ease: Slide easing
more --badge-offset-x: Offset X
more --badge-offset-y: Offset Y
more --badge-blur: Blur
[Badge close] badge dot
--badge-pop-close-dur: Duration
--badge-close-ease: Easing
more --badge-fade-close-dur: Fade duration
more [Count pop] badge number
--digit-dur: Duration
--digit-distance: Distance
--digit-blur: Blur
--digit-ease: Easing
--digit-stagger: Stagger
more [Button press] buttons
--press-scale: Scale
--press-dur: Duration
--ease-smooth-out: Easing
*/
:root {
  --badge-slide-dur: 260ms;
  --badge-pop-dur: 500ms;
  --badge-pop-close-dur: 180ms;
  --badge-fade-dur: 400ms;
  --badge-fade-close-dur: 180ms;
  --badge-blur: 2px;
  --badge-offset-x: -8.2px;
  --badge-offset-y: 12.4px;
  --badge-slide-ease: cubic-bezier(0.22, 1, 0.36, 1);
  --badge-pop-ease: cubic-bezier(0.34, 1.36, 0.64, 1);
  --badge-close-ease: cubic-bezier(0.4, 0, 0.2, 1);
  --digit-dur: 500ms;
  --digit-distance: 8px;
  --digit-stagger: 70ms;
  --digit-blur: 2px;
  --digit-ease: cubic-bezier(0.34, 1.45, 0.64, 1);
  --digit-dir-x: 0;
  --digit-dir-y: 1;
  --ring-dur: 900ms;
  --ring-angle: 18deg;
  --ring-ease: cubic-bezier(0.36, 0.07, 0.19, 0.97);
  --press-scale: 0.97;
  --press-dur: 150ms;
  --ease-smooth-out: cubic-bezier(0.22, 1, 0.36, 1);
}

.nb { display: flex; flex-direction: column; align-items: center; gap: 24px; color: var(--stage-fg); }
.nb *, .nb *::before, .nb *::after { box-sizing: border-box; }
.nb :where(button) { font: inherit; border: 0; padding: 0; background: none; color: inherit; cursor: pointer; }

.nb-bell {
  position: relative;
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: var(--stage-surface);
  box-shadow: 0 1px 3px 0 rgba(0,0,0,.04), inset 0 0 0 1px rgba(0,0,0,.08), inset 0 -1px 0 0 rgba(0,0,0,.08);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--stage-muted);
}
html[data-theme="dark"] .nb-bell {
  background: rgba(255,255,255,.04);
  box-shadow: 0 1px 1px 0 rgba(0,0,0,.24), inset 0 0 0 1px rgba(255,255,255,.04), inset 0 1px 0 0 rgba(255,255,255,.06);
}
.nb-ring { display: flex; transform-origin: 50% 15%; }
.nb-ring .hi { width: 20px; height: 20px; }
.nb-ring.is-ringing { animation: nb-ring var(--ring-dur) var(--ring-ease); }
@keyframes nb-ring {
  0% { transform: rotate(0); }
  15% { transform: rotate(var(--ring-angle)); }
  30% { transform: rotate(calc(var(--ring-angle) * -0.85)); }
  45% { transform: rotate(calc(var(--ring-angle) * 0.6)); }
  60% { transform: rotate(calc(var(--ring-angle) * -0.4)); }
  78% { transform: rotate(calc(var(--ring-angle) * 0.18)); }
  100% { transform: rotate(0); }
}

@keyframes t-badge-slide-in {
  from { transform: translate(var(--badge-offset-x), var(--badge-offset-y)); }
  to { transform: translate(0, 0); }
}
.t-badge { position: absolute; top: -4px; right: -6px; pointer-events: none; }
.t-badge[data-open="true"] { animation: t-badge-slide-in var(--badge-slide-dur) var(--badge-slide-ease); }
.t-badge-dot {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background-image: linear-gradient(-51.52deg, rgb(238, 41, 51) 13.929%, rgb(236, 2, 72) 112.7%);
  color: #fff;
  font-size: 11px;
  line-height: 1;
  font-weight: 500;
  font-variant-numeric: tabular-nums;
  box-shadow: 0 0.338px 1.351px 0 rgba(0,0,0,.17), 0 0.676px 2.703px 0 rgba(0,0,0,.04), inset 0 -0.338px 0 0 rgba(0,0,0,.16);
  transform-origin: center;
  transform: scale(1);
  opacity: 1;
  filter: blur(0);
  transition: transform var(--badge-pop-dur) var(--badge-pop-ease), opacity var(--badge-fade-dur) var(--badge-pop-ease), filter var(--badge-pop-dur) var(--badge-pop-ease);
}
.t-badge[data-open="false"] .t-badge-dot {
  transform: scale(0);
  opacity: 0;
  filter: blur(var(--badge-blur));
  transition: transform var(--badge-pop-close-dur) var(--badge-close-ease), opacity var(--badge-fade-close-dur) var(--badge-close-ease), filter var(--badge-pop-close-dur) var(--badge-close-ease);
}

@keyframes t-digit-pop-in {
  0% { transform: translate(calc(var(--digit-distance) * var(--digit-dir-x)), calc(var(--digit-distance) * var(--digit-dir-y))); opacity: 0; filter: blur(var(--digit-blur)); }
  100% { transform: translate(0, 0); opacity: 1; filter: blur(0); }
}
.t-digit-group { display: inline-flex; align-items: baseline; }
.t-digit { display: inline-block; }
.t-digit-group.is-animating .t-digit { animation: t-digit-pop-in var(--digit-dur) var(--digit-ease) both; }

.nb-actions { display: flex; gap: 8px; }
.nb-btn {
  height: 36px;
  padding: 0 14px;
  border-radius: 40px;
  font-size: 13px;
  line-height: 20px;
  font-weight: 500;
  transition: transform var(--press-dur) var(--ease-smooth-out), background-color var(--press-dur) var(--ease-smooth-out), filter var(--press-dur) var(--ease-smooth-out);
}
.nb-btn:is(:active,.is-pressed) { transform: scale(var(--press-scale)); }
.nb-primary { background: var(--stage-accent); color: var(--stage-on-accent); box-shadow: 0 1px 2px 0 rgba(0,0,0,.2); }
html[data-theme="dark"] .nb-primary { box-shadow: 0 1px 2px 0 rgba(0,0,0,.4); }
.nb-secondary { background: rgba(0,0,0,.04); }
html[data-theme="dark"] .nb-secondary { background: rgba(255,255,255,.07); }
@media (hover: hover) {
  .nb-secondary:hover { background: rgba(0,0,0,.06); }
  html[data-theme="dark"] .nb-secondary:hover { background: rgba(255,255,255,.1); }
  .nb-primary:hover { filter: brightness(1.15); }
}
.nb-btn:focus-visible { outline: none; box-shadow: 0 0 0 2px var(--stage-surface), 0 0 0 4px var(--stage-accent); }

@media (prefers-reduced-motion: reduce) {
  .nb-ring.is-ringing { animation: none; }
  .t-badge, .t-badge-dot, .t-digit-group .t-digit, .nb-btn { animation: none !important; transition: none !important; }
}

