import { useRef, useState } from "react";

function playChime(ctx: AudioContext) {
  const now = ctx.currentTime;
  [880, 1318.5].forEach((freq, i) => {
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = "sine";
    osc.frequency.value = freq;
    const t = now + i * 0.13;
    gain.gain.setValueAtTime(0.0001, t);
    gain.gain.exponentialRampToValueAtTime(0.22, t + 0.015);
    gain.gain.exponentialRampToValueAtTime(0.0001, t + 0.7);
    osc.connect(gain).connect(ctx.destination);
    osc.start(t);
    osc.stop(t + 0.75);
  });
}

export default function NotificationBell() {
  const [count, setCount] = useState(0);
  const [open, setOpen] = useState(false);
  const [ring, setRing] = useState(0);
  const ctxRef = useRef<AudioContext | null>(null);

  const notify = () => {
    try {
      if (!ctxRef.current) {
        const AC = window.AudioContext || (window as any).webkitAudioContext;
        ctxRef.current = new AC();
      }
      const ctx = ctxRef.current!;
      if (ctx.state === "suspended") ctx.resume();
      playChime(ctx);
    } catch (e) {}
    setCount(open ? Math.min(count + 1, 99) : 1);
    setOpen(true);
    setRing((r) => r + 1);
  };

  const clear = () => setOpen(false);
  const label = count > 9 ? "9+" : String(count);

  return (
    <div className="nb">
      <div className="nb-bell" role="img" aria-label={open ? `${count} new notifications` : "No new notifications"}>
        <span
          key={ring}
          className={"nb-ring" + (ring > 0 ? " is-ringing" : "")}
        >
          <svg className="hi" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeLinecap="round" strokeLinejoin="round" strokeWidth="1.8" aria-hidden="true"><path d="M14.857 17.082a23.848 23.848 0 0 0 5.454-1.31A8.967 8.967 0 0 1 18 9.75V9A6 6 0 0 0 6 9v.75a8.967 8.967 0 0 1-2.312 6.022c1.733.64 3.56 1.085 5.455 1.31m5.714 0a24.255 24.255 0 0 1-5.714 0m5.714 0a3 3 0 1 1-5.714 0"/></svg>
        </span>
        <span className="t-badge" data-open={open ? "true" : "false"} aria-hidden="true">
          <span className="t-badge-dot">
            <span key={label + "-" + ring} className="t-digit-group is-animating">
              {label.split("").map((ch, i) => (
                <span className="t-digit" key={i}>{ch}</span>
              ))}
            </span>
          </span>
        </span>
      </div>
      <div className="nb-actions">
        <button type="button" className="nb-btn nb-primary" onClick={notify}>Notify</button>
        <button type="button" className="nb-btn nb-secondary" onClick={clear}>Clear</button>
      </div>
    </div>
  );
}
